mapper.select:
SELECT COUNT(*)
FROM BOARD B
INNER JOIN BOARD_TYPE_SUB BTS ON B.B_SUB_NO = BTS.B_SUB_NO
INNER JOIN BOARD_TYPE_MAIN BTM ON BTS.B_MAIN_NO = BTM.B_MAIN_NO
WHERE 1=1


		AND B.B_STATUS = 'T'


		AND B.B_STATUS = 'Y'




	AND BTM.B_MAIN_NO = #{bMainNo}



	AND B.B_SUB_NO = #{bSubNo}



	AND BTS.B_SUB_TYPE = #{integratedCategory}



	AND BTS.B_SUB_TYPE = #{localCategory}



	AND B.LOCAL_NO = #{localNo}



	AND (


				B.TITLE LIKE CONCAT('%', #{keyword}, '%')


				B.B_CONTENT LIKE CONCAT('%', #{keyword}, '%')


				B.USER_ID LIKE CONCAT('%', #{keyword}, '%')


				(
					B.TITLE LIKE CONCAT('%', #{keyword}, '%')
					OR B.B_CONTENT LIKE CONCAT('%', #{keyword}, '%')
					OR B.USER_ID LIKE CONCAT('%', #{keyword}, '%')
				)


	)

mapper.update:
UPDATE BOARD
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE BOARD_NO = #{boardNo}

mapper.select:
 SELECT IFNULL(A.LIKE_CNT, 0) AS LIKE_CNT, CASE
		WHEN B.BOARD_NO IS NULL THEN 'N' ELSE 'Y' END AS MY_LIKE FROM ( SELECT
		BOARD_NO, COUNT(*) AS LIKE_CNT FROM BOARD_LIKE WHERE BOARD_NO =
		#{boardNo} GROUP BY BOARD_NO ) A LEFT JOIN ( SELECT BOARD_NO FROM
		BOARD_LIKE WHERE BOARD_NO = #{boardNo} 
			AND USER_ID = #{sessionId}
		 ) B ON A.BOARD_NO = B.BOARD_NO
		UNION SELECT 0 AS LIKE_CNT, 'N' AS MY_LIKE FROM DUAL WHERE NOT EXISTS (
		SELECT 1 FROM BOARD_LIKE WHERE BOARD_NO = #{boardNo} ) LIMIT 1

SELECT BOARD_NO, USER_ID
FROM BOARD_LIKE
WHERE BOARD_NO = #{boardNo}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM BOARD_LIKE
WHERE BOARD_NO = #{boardNo}
AND USER_ID = #{userId}

